package com.mendes.scheduling_platform.pricing;
import com.mendes.scheduling_platform.addon.*; import com.mendes.scheduling_platform.venue.*; import com.mendes.scheduling_platform.venuepackage.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.*; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class PricingServiceTest { @Mock VenuePackageRepository packages; @Mock AddonRepository addons; PricingService service; OffsetDateTime start=OffsetDateTime.parse("2026-09-10T10:00:00-03:00"); @BeforeEach void setUp(){service=new PricingService(packages,addons);}
 @Test void hourlyPriceUsesDuration(){Venue v=venue(Venue.PricingType.HOURLY);v.setBasePrice(new BigDecimal("80"));v.setMinimumDurationMinutes(60);v.setMaximumDurationMinutes(240);v.setDurationStepMinutes(60);var q=service.quote(1L,v,start,120,null,null,List.of());assertEquals(new BigDecimal("160.00"),q.totalAmount());assertEquals(start.plusHours(2),q.endDateTime());}
 @Test void packageUsesSnapshotPrice(){Venue v=venue(Venue.PricingType.PACKAGE);VenuePackage p=new VenuePackage();p.setId(7L);p.setTenantId(1L);p.setVenueId(9L);p.setDurationMinutes(120);p.setPrice(new BigDecimal("150"));p.setActive(true);when(packages.findByIdAndTenantIdAndVenueId(7L,1L,9L)).thenReturn(Optional.of(p));var q=service.quote(1L,v,start,null,null,7L,List.of());assertEquals(new BigDecimal("150.00"),q.totalAmount());}
 @Test void perUnitAddonIsAdded(){Venue v=venue(Venue.PricingType.FIXED_SLOT);v.setBasePrice(new BigDecimal("100"));v.setSlotDurationMinutes(60);Addon a=new Addon();a.setId(3L);a.setVenueId(9L);a.setTenantId(1L);a.setPrice(new BigDecimal("5"));a.setPricingType(Addon.PricingType.PER_UNIT);a.setActive(true);when(addons.findByIdAndTenantIdAndVenueId(3L,1L,9L)).thenReturn(Optional.of(a));var q=service.quote(1L,v,start,null,null,null,List.of(new PricingService.AddonRequest(3L,10)));assertEquals(new BigDecimal("150.00"),q.totalAmount());}
 private Venue venue(Venue.PricingType type){Venue v=new Venue();v.setId(9L);v.setTenantId(1L);v.setPricingType(type);v.setPrice(BigDecimal.ZERO);v.setDurationMinutes(60);return v;} }
